  const { openModal } = useModal();

  const handleNavClick = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault();
    const element = document.querySelector(href);
    if (element) {
      const headerOffset = 80;
      const elementPosition = element.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.pageYOffset - headerOffset;

      window.scrollTo({
        top: offsetPosition,
        behavior: "smooth"
      });
    }
    setIsMenuOpen(false);
  };

  return (
    <header className="fixed top-0 left-0 right-0 shadow-lg z-[60] bg-via-blue text-white">
      {/* Top Bar - Minimal */}
      <div className="bg-black/20 text-white py-1.5 text-xs hidden md:block">
        <div className="container mx-auto px-4 flex justify-between items-center">
          <div className="flex gap-6 opacity-80">
            <span className="flex items-center gap-2"><Phone size={12} className="text-via-yellow" /> {CONTACT_INFO.phone}</span>
            <span className="flex items-center gap-2"><Mail size={12} className="text-via-yellow" /> {CONTACT_INFO.email}</span>
          </div>
          <div className="flex gap-4">
            <a href={CONTACT_INFO.facebook} target="_blank" rel="noopener noreferrer" className="hover:text-via-yellow transition-colors"><Facebook size={12} /></a>
            <a href={CONTACT_INFO.instagram} target="_blank" rel="noopener noreferrer" className="hover:text-via-yellow transition-colors"><Instagram size={12} /></a>
          </div>
        </div>
      </div>

      {/* Main Nav */}
      <div className="container mx-auto px-4 py-3 flex justify-between items-center">
        {/* Logo */}
        <a href="#inicio" onClick={(e) => handleNavClick(e, '#inicio')} className="w-40 md:w-48">
          <img src={IMAGES.LOGO_WHITE} alt="Via Solar" className="w-full h-auto object-contain" />
        </a>

        {/* Desktop Nav */}
        <nav className="hidden lg:flex items-center gap-6 font-heading text-[13px] font-bold">
          {NAV_ITEMS.map((item) => (
            <a 
              key={item.label} 
              href={item.href} 
              onClick={(e) => handleNavClick(e, item.href)}
              className="hover:text-via-yellow transition-colors uppercase tracking-wider"
            >
              {item.label}
            </a>
          ))}
        </nav>

        {/* CTA Button Header */}
        <div className="hidden lg:flex">
          <button 
            onClick={openModal}
            className="bg-via-yellow text-via-blue-dark font-extrabold py-2 px-6 rounded-full text-xs hover:bg-yellow-400 transition shadow-md uppercase flex items-center gap-2"
          >
            <WhatsAppIcon size={14} /> Falar com Consultor
          </button>
        </div>

        {/* Mobile Toggle */}
        <button className="lg:hidden" onClick={() => setIsMenuOpen(!isMenuOpen)}>
          {isMenuOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isMenuOpen && (
        <div className="lg:hidden bg-via-blue-dark border-t border-white/10 animate-in slide-in-from-top duration-300">
          <nav className="flex flex-col p-4 gap-4 font-heading font-bold uppercase text-sm">
            {NAV_ITEMS.map((item) => (
              <a key={item.label} href={item.href} onClick={(e) => handleNavClick(e, item.href)} className="py-2 border-b border-white/5">
                {item.label}
              </a>
            ))}
            <button onClick={() => { openModal(); setIsMenuOpen(false); }} className="bg-via-yellow text-via-blue-dark font-bold py-4 rounded-xl flex justify-center items-center gap-2 mt-2">
              <WhatsAppIcon size={18} /> Orçamento Grátis
            </button>
          </nav>
        </div>
      )}
